def normalize_once(field, raw_present, raw):
    if not raw_present or not isinstance(raw, str):
        return None, "STOP"
    trim = {32, 9, 10, 13, 0x200B, 0x200C, 0x200D, 0x2060, 0xFEFF}
    start, end = 0, len(raw)
    while start < end and ord(raw[start]) in trim:
        start += 1
    while end > start and ord(raw[end-1]) in trim:
        end -= 1
    value = raw[start:end]
    if field == "filesystem_id":
        value = value.lower()
    if field == "filesystem_id" or (field == "filesystem_mount" and value != "/"):
        while value.endswith("/"):
            value = value[:-1]
    label = "STOP" if value == "" or value.lower() == "null" else "PASS"
    return value, label
